<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $invoice->invoice_number }}</title><style>body{font-family:Arial,sans-serif;color:#222;margin:32px}header{display:flex;justify-content:space-between}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{padding:9px;border-bottom:1px solid #ccc;text-align:left}.num{text-align:right}.totals{margin-left:auto;width:360px}@media print{.no-print{display:none}body{margin:0}}</style></head><body><button class="no-print" onclick="window.print()">Print</button><header><div><h1>{{ $invoice->document_type === 'credit_note' ? 'Credit note' : 'Invoice' }}</h1><strong>{{ $invoice->invoice_number }}</strong></div><div class="num">{{ $invoice->seller_name }}<br>{{ $invoice->seller_address }}<br>{{ $invoice->seller_contact }}</div></header><p><strong>Bill to:</strong> {{ $invoice->client_name }}<br>{{ $invoice->client_address }}<br>{{ $invoice->client_contact }}</p><p><strong>Issue:</strong> {{ optional($invoice->issue_date)->format('Y-m-d') }} · <strong>Due:</strong> {{ $invoice->due_date->format('Y-m-d') }}</p><table><thead><tr><th>Description</th><th class="num">Quantity</th><th class="num">Unit</th><th class="num">Discount</th><th class="num">Tax</th><th class="num">Total</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->description }}</td><td class="num">{{ $item->quantity }}</td><td class="num">{{ $item->unit_price }}</td><td class="num">{{ $item->discount_amount }}</td><td class="num">{{ $item->tax_amount }}</td><td class="num">{{ $item->line_total }}</td></tr>@endforeach</tbody></table><table class="totals"><tr><td>Subtotal</td><td class="num">{{ $invoice->subtotal }}</td></tr><tr><td>Discount</td><td class="num">-{{ $invoice->discount_total }}</td></tr><tr><td>Tax</td><td class="num">{{ $invoice->tax_total }}</td></tr><tr><th>Total</th><th class="num">{{ $invoice->currency_code }} {{ $invoice->total }}</th></tr><tr><td>Payments</td><td class="num">{{ $applied }}</td></tr><tr><th>Balance</th><th class="num">{{ $invoice->currency_code }} {{ $balance }}</th></tr></table></body></html>
